    if 'RUST' in os.environ: o.lang_scopes.append(('rust',os.environ['RUST']))
    if 'GO' in os.environ: o.lang_scopes.append(('go',os.environ['GO']))
    if 'C' in os.environ: o.lang_scopes.append(('c',os.environ['C']))
    if 'CSHARP' in os.environ: o.lang_scopes.append(('csharp',os.environ['CSHARP']))
    if 'TYPESCRIPT' in os.environ: o.lang_scopes.append(('typescript',os.environ['TYPESCRIPT']))
