                    if base=='class-methods' and 'classmethod' not in decnames: continue
                    if base=='static-methods' and 'staticmethod' not in decnames: continue
                    out.append(node_span(n, decorators=(base=='methods')))
        return out
    if base=='function-names':
        for n in ast.walk(tree):
            if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)):
                s=abspos(n.lineno,n.col_offset); line=text.splitlines()[n.lineno-1]
                m=re.search(r'\bdef\s+([A-Za-z_][A-Za-z0-9_]*)', line[n.col_offset:])
                if m: out.append((s+m.start(1), s+m.end(1)))
        return out
    if base=='function-calls':
        for n in ast.walk(tree):
            if isinstance(n, ast.Call):
                f=n.func
                if isinstance(f, ast.Name): out.append(node_span(f))
                elif isinstance(f, ast.Attribute):
                    sp=node_span(f); raw=text[sp[0]:sp[1]]; out.append((sp[1]-len(f.attr), sp[1]))
        return out
    if base=='imports':
        for n in ast.walk(tree):
            if isinstance(n, ast.Import):
                line=text.splitlines()[n.lineno-1]; baseabs=abspos(n.lineno,0)
                for al in n.names:
                    for m in re.finditer(re.escape(al.name), line): out.append((baseabs+m.start(),baseabs+m.end()))
                    if al.asname:
                        for m in re.finditer(r'\b'+re.escape(al.asname)+r'\b', line): out.append((baseabs+m.start(),baseabs+m.end()))
            elif isinstance(n, ast.ImportFrom):
                line=text.splitlines()[n.lineno-1]; baseabs=abspos(n.lineno,0)
                names=[]
                if n.module: names.append(n.module)
                for al in n.names:
                    names.append(al.name)
                    if al.asname: names.append(al.asname)
                for name in names:
                    for m in re.finditer(r'(?<![A-Za-z0-9_])'+re.escape(name)+r'(?![A-Za-z0-9_])', line): out.append((baseabs+m.start(),baseabs+m.end()))
        return merge_spans(out)
    if base=='globals':
        for n in tree.body:
            if isinstance(n,(ast.Assign,ast.AnnAssign)):
                out.append(node_span(n.targets[0] if isinstance(n,ast.Assign) else n.target))
        return out
    if base=='variable-identifiers':
        for n in ast.walk(tree):
            if isinstance(n,(ast.Assign,ast.AnnAssign)):
                targets=n.targets if isinstance(n,ast.Assign) else [n.target]
                for t in targets:
                    if isinstance(t,ast.Name): out.append(node_span(t))
                    elif isinstance(t,ast.Attribute): out.append((node_span(t)[1]-len(t.attr),node_span(t)[1]))
        return out
    if base=='types':
        for n in ast.walk(tree):
            for attr in ('annotation','returns'):
                ann=getattr(n,attr,None)
                if ann is not None: out.append(node_span(ann))
        return out
    if base=='identifiers':
        try:
            for tok in tokenize.generate_tokens(io.StringIO(text).readline):
                if tok.type==token.NAME and not keyword.iskeyword(tok.string):
                    out.append((line_col_abs(offs,*tok.start),line_col_abs(offs,*tok.end)))
        except Exception: pass
        return out
    return []

def split_filter(spec):
    if '~' in spec:
        a,b=spec.split('~',1); return a,b
    return spec,None

def scan_strings(text, content=True):
    out=[]; i=0; n=len(text)
    while i<n:
        if text[i] in ('"',"'"):
            q=text[i]; start=i; i+=1; esc=False
            while i<n:
                ch=text[i]
                if esc: esc=False; i+=1; continue
                if ch=='\\': esc=True; i+=1; continue
                if ch==q:
                    end=i+1; out.append((start+1 if content else start, i if content else end)); i=end; break
                if ch=='\n': break
                i+=1
            else: break
        i+=1
    return [(a,b) for a,b in out if b>a]

def scan_comments(text, hashes=False, doc=False, rust=False):
    out=[]
    # block comments
    for m in re.finditer(r'/\*.*?\*/', text, re.S): out.append((m.start(),m.end()))
    for m in re.finditer(r'//[^\n]*', text):
        s=text[m.start():m.end()]
        if rust and doc:
            if s.startswith('///') or s.startswith('//!'): out.append((m.start(),m.end()))
        elif rust:
            if not (s.startswith('///') or s.startswith('//!')): out.append((m.start(),m.end()))
        else: out.append((m.start(),m.end()))
    if hashes:
        for m in re.finditer(r'#[^\n]*', text): out.append((m.start(),m.end()))
    return merge_spans(out)

def brace_span_from(text, start):
    lb=text.find('{', start)
    if lb<0:
        nl=text.find('\n', start); return (start, len(text) if nl<0 else nl)
    depth=0; i=lb
    in_str=None; esc=False
    while i<len(text):
        ch=text[i]
        if in_str:
            if esc: esc=False
            elif ch=='\\': esc=True
            elif ch==in_str: in_str=None
        else:
            if ch in ('"',"'"): in_str=ch
            elif ch=='{': depth+=1
            elif ch=='}':
                depth-=1
                if depth==0: return (start,i+1)
        i+=1
    return (start, len(text))

def keyword_blocks(text, pattern, name_filter=None):
    out=[]
    for m in re.finditer(pattern, text, re.M):
        name=m.groupdict().get('name') if hasattr(m,'groupdict') else None
        if name_filter and name and not re.search(name_filter,name): continue
        out.append(brace_span_from(text,m.start()))
    return out

def generic_spans(text, lang, spec):
    base,filt=split_filter(spec)
    if base=='__query__': return [(0,len(text))]
    if base in ('comments','comment'):
        return scan_comments(text, hashes=(lang=='hcl'), rust=(lang=='rust'))
    if base=='doc-comments': return scan_comments(text, rust=True, doc=True)
    if base=='strings':
        content = lang in ('python','rust','typescript','hcl','go')
        if lang in ('c','csharp'): content=False
        return scan_strings(text, content=content)
    if base in ('identifier','identifiers','type-identifier'):
        return [(m.start(),m.end()) for m in re.finditer(r'\b[A-Za-z_][A-Za-z0-9_]*\b', text) if not keyword.iskeyword(m.group(0))]
    if lang=='hcl':
        if base in ('variable','resource','data','output','provider','terraform','locals','module'):
            return keyword_blocks(text, r'(?m)^\s*'+re.escape(base)+r'\b')
        if base in ('variables','resource-names','resource-types','data-names','data-sources'):
            return scan_strings(text, content=True)+[(m.start(),m.end()) for m in re.finditer(r'\bvar\.[A-Za-z_][A-Za-z0-9_]*\b', text)]
    if lang=='go':
        if base in ('func','method','free-func','init-func'):
            pat=r'(?m)^\s*func(?:\s*\([^)]*\))?\s+(?P<name>[A-Za-z_][A-Za-z0-9_]*)\b'
            return keyword_blocks(text, pat, filt)
        if base in ('struct','interface'):
            return keyword_blocks(text, r'(?m)^\s*type\s+(?P<name>[A-Za-z_][A-Za-z0-9_]*)\s+'+base+r'\b', filt)
        if base in ('imports','const','var','defer','select','go','switch','goto'):
            return line_keyword_spans(text, base if base!='imports' else 'import')
        if base in ('type-def','type-alias'): return line_keyword_spans(text,'type')
        if base=='struct-tags': return [(m.start(1),m.end(1)) for m in re.finditer(r'`([^`]*)`', text)]
        if base=='expression': return all_nonempty_line_spans(text)
    if lang=='rust':
        if base in ('fn','impl-fn','priv-fn','pub-fn','const-fn','async-fn','unsafe-fn','extern-fn','test-fn'):
            return keyword_blocks(text, r'(?m)^\s*(?:pub(?:\([^)]*\))?\s+)?(?:const\s+)?(?:async\s+)?(?:unsafe\s+)?(?:extern\s+)?fn\s+(?P<name>[A-Za-z_][A-Za-z0-9_]*)\b', filt)
        if base in ('struct','priv-struct','pub-struct','pub-crate-struct','pub-self-struct','pub-super-struct'):
            return keyword_blocks(text, r'(?m)^\s*(?:pub(?:\([^)]*\))?\s+)?struct\s+(?P<name>[A-Za-z_][A-Za-z0-9_]*)\b', filt)
        if base in ('enum','priv-enum','pub-enum','type-def'):
            return keyword_blocks(text, r'(?m)^\s*(?:pub(?:\([^)]*\))?\s+)?(?:enum|union|struct)\s+(?P<name>[A-Za-z_][A-Za-z0-9_]*)\b', filt)
        if base in ('trait','impl','impl-type','impl-trait','mod','mod-tests'):
            kw='mod' if base.startswith('mod') else ('trait' if base=='trait' else 'impl')
            return keyword_blocks(text, r'(?m)^\s*(?:pub\s+)?'+kw+r'\b(?:\s+(?P<name>[A-Za-z_][A-Za-z0-9_]*))?', filt)
        if base in ('uses','attribute','unsafe','closure','enum-variant'):
            if base=='uses': return line_keyword_spans(text,'use')
            if base=='attribute': return [(m.start(),m.end()) for m in re.finditer(r'#\[[^\]]*\]', text)]
            if base=='unsafe': return [(m.start(),m.end()) for m in re.finditer(r'\bunsafe\b', text)]
    if lang in ('typescript','csharp'):
        if base in ('class','interface','enum','namespace','try-catch','export','struct','method','constructor','property'):
            kw={'try-catch':'try'}.get(base,base)
            return keyword_blocks(text, r'(?m)^\s*(?:export\s+)?(?:async\s+)?'+re.escape(kw)+r'\b(?:\s+(?P<name>[A-Za-z_][A-Za-z0-9_]*))?', filt)
        if base in ('function','async-function','sync-function'):
            return keyword_blocks(text, r'(?m)^\s*(?:export\s+)?(?:async\s+)?function\s+(?P<name>[A-Za-z_][A-Za-z0-9_]*)\b', filt)
        if base in ('imports','usings'): return line_keyword_spans(text, 'import' if lang=='typescript' else 'using')
        if base in ('var-decl','let','const','var','variable-declaration','field'):
            kws=['let','const','var'] if base=='var-decl' else [base]
            out=[]
            for kw in kws: out += line_keyword_spans(text,kw)
            return out
        if base=='attribute': return [(m.start(1),m.end(1)) for m in re.finditer(r'\[\s*([A-Za-z_][A-Za-z0-9_]*)', text)]
    if lang=='c':
        if base=='includes': return line_keyword_spans(text, '#include')
        if base in ('function','function-def','function-decl'):
            return keyword_blocks(text, r'(?m)^\s*(?:[A-Za-z_][\w\s\*]+\s+)+(?P<name>[A-Za-z_][A-Za-z0-9_]*)\s*\([^;]*\)\s*\{?', filt)
        if base in ('struct','enum','union','type-def'):
            kw='(?:struct|enum|union)' if base=='type-def' else base
            return keyword_blocks(text, r'(?m)^\s*(?:typedef\s+)?'+kw+r'\b(?:\s+(?P<name>[A-Za-z_][A-Za-z0-9_]*))?', filt)
        if base in ('switch','if','for','while','do'):
            return keyword_blocks(text, r'(?m)^\s*'+base+r'\b')
        if base in ('variable','declaration'): return [(m.start(), m.end()) for m in re.finditer(r'(?m)^\s*[A-Za-z_][\w\s\*]+\s+[A-Za-z_][A-Za-z0-9_]*[^;]*;', text)]
        if base=='call-expression': return [(m.start(),m.end()) for m in re.finditer(r'\b[A-Za-z_][A-Za-z0-9_]*\s*\([^)]*\)', text)]
    return []

def line_keyword_spans(text, kw):
    out=[]
    if kw.startswith('#'):
        pat=r'(?m)^\s*'+re.escape(kw)+r'[^\n]*'
    else:
        pat=r'(?m)^\s*'+re.escape(kw)+r'\b[^\n]*'
    for m in re.finditer(pat,text): out.append((m.start(),m.end()))
    return out

def language_spans(text, scopes, join=False):
    if not scopes: return [(0,len(text))]
    sets=[]
    for lang,spec in scopes:
        if lang=='python': sets.append(python_spans(text,spec))
        else: sets.append(generic_spans(text,lang,spec))
    if join:
        spans=[]
        for s in sets: spans+=s
        return merge_spans(spans)
    cur=[(0,len(text))]
    for s in sets:
        cur=intersect_spans(cur,s)
    return cur

@dataclass
class MatchRec:
    start:int; end:int; text:str; match:object|None=None; seg_start:int=0

def compile_regex(pattern):
    try:
        return re.compile(pattern)
    except re.error as ex:
        raise RuntimeSrgnError(f"Failed building regex\n\nCaused by:\n    Invalid regex: {ex}")

def find_matches(text, spans, pattern, literal=False):
    out=[]
    if literal:
        if pattern=='': return []
        for a,b in spans:
            pos=a
            while True:
                idx=text.find(pattern,pos,b)
                if idx<0: break
                out.append(MatchRec(idx,idx+len(pattern),text[idx:idx+len(pattern)])); pos=idx+max(1,len(pattern))
        return out
    rx=compile_regex(pattern)
    for a,b in spans:
        segment=text[a:b]
        for m in rx.finditer(segment):
            if m.end()==m.start(): continue
            out.append(MatchRec(a+m.start(),a+m.end(),m.group(0),m,a))
    return sorted(out, key=lambda m:(m.start,m.end))

def expand_replacement(rep, rec):
    if rec.match is None: return rep
    m=rec.match
    def repl_var(mm):
        name=mm.group(1) or mm.group(2)
        if name is None: return '$'
        try:
            if name.isdigit():
                val=m.group(int(name))
            else:
                val=m.group(name)
        except Exception:
            raise RuntimeSrgnError(f"Error applying: Error in an action: Action failed in replacement: Error in variable expressions: Undefined variable, unable to substitute: '{name}'")
        return '' if val is None else val
    return re.sub(r'\$\{([^}]+)\}|\$([A-Za-z_][A-Za-z0-9_]*|[0-9]+)|\$\$', repl_var, rep)

def upper_unicode(s):
    return ''.join('ẞ' if ch=='ß' else ch.upper() for ch in s)

def titlecase(s):
    # Close to the observed titlecase crate: title each word in the scoped string.
    def one(m):
        w=m.group(0)
        if not w: return w
        return upper_unicode(w[0]) + w[1:].lower()
    return re.sub(r'[A-Za-zÄÖÜäöüẞß]+', one, s)

def normalize_text(s):
    return ''.join(ch for ch in unicodedata.normalize('NFD', s) if unicodedata.category(ch) != 'Mn')

SYMS=[('<->','↔'),('!=','≠'),('<=','≤'),('>=','≥'),('->','→'),('<-','←'),('=>','⇒'),('---','—'),('--','–')]

def symbols_text(s, invert=False):
    pairs=[(b,a) for a,b in SYMS] if invert else SYMS
    for a,b in pairs: s=s.replace(a,b)
    return s

def replace_case(word, old, new):
    # preserve common capitalization forms
    def sub(m):
        val=m.group(0)
        if val.isupper(): return new.upper().replace('ß','ẞ')
        if val[0].isupper(): return new[0].upper()+new[1:]
        return new
    return re.sub(old, sub, word, flags=re.I)

def german_word(w, naive=False, prefer=False):
    if naive:
        reps=[('Ae','Ä'),('Oe','Ö'),('Ue','Ü'),('AE','Ä'),('OE','Ö'),('UE','Ü'),('ae','ä'),('oe','ö'),('ue','ü'),('SS','ẞ'),('ss','ß')]
        for a,b in reps: w=w.replace(a,b)
        return w
    orig=w
    # Known/legal-word exceptions observed in the binary.
    if re.search(r'(?i)^koeffizient', w): return w
    if prefer and re.search(r'(?i)^(busse|strasse)$', w): return w
    # Compound-friendly substitutions, avoiding true vowel sequences such as Abenteuer.
    w=replace_case(w, r'ae', 'ä')
    w=replace_case(w, r'oe', 'ö')
    w=re.sub(r'(?i)ue', lambda m: ('Ü' if m.group(0)[0].isupper() else 'ü') if not (m.end()<len(w) and w[m.end()] in 'rR' and m.start()>0 and w[m.start()-1] in 'eE') else m.group(0), w)
    # ss -> ß, with a few common words handled by the same rule.
    w=re.sub(r'SS', 'ẞ', w)
    w=re.sub(r'Ss', 'ẞ', w)
    w=re.sub(r'ss', 'ß', w)
    return w

def german_text(s, naive=False, prefer=False):
    return re.sub(r'[A-Za-zÄÖÜäöüẞß]+', lambda m: german_word(m.group(0),naive,prefer), s)

def transform_piece(piece, rec, o):
    if o.replacement is not None:
        piece=expand_replacement(o.replacement, rec)
    if o.upper: piece=upper_unicode(piece)
    if o.lower: piece=piece.lower()
    if o.titlecase: piece=titlecase(piece)
    if o.normalize: piece=normalize_text(piece)
    if o.german: piece=german_text(piece, o.german_naive, o.german_prefer_original)
    if o.symbols: piece=symbols_text(piece, o.invert)
    return piece

def has_composable(o): return o.upper or o.lower or o.titlecase or o.normalize or o.german or o.symbols or o.replacement is not None

def apply_actions(text, matches, o):
    if o.delete:
        repls=[(m.start,m.end,'') for m in matches]
    elif o.squeeze:
        # Keep the first in each adjacent run, drop following consecutive matches.
        repls=[]; prev_end=None
        for m in matches:
            if prev_end is not None and m.start==prev_end:
                repls.append((m.start,m.end,''))
            prev_end=m.end
        if has_composable(o):
            # Also transform retained matches.
            drops={(a,b) for a,b,_ in repls}; repls2=list(repls)
            for m in matches:
                if (m.start,m.end) not in drops:
                    repls2.append((m.start,m.end,transform_piece(m.text,m,o)))
            repls=sorted(repls2)
    else:
        repls=[(m.start,m.end,transform_piece(m.text,m,o)) for m in matches]
    repls=sorted(repls, key=lambda x:(x[0],x[1]))
    out=[]; last=0
    for a,b,r in repls:
        if a<last: continue
        out.append(text[last:a]); out.append(r); last=b
    out.append(text[last:])
    return ''.join(out)

def line_for_pos(offs, pos):
    # returns 1-based line index
    lo=0; hi=len(offs)
    while lo+1<hi:
        mid=(lo+hi)//2
        if offs[mid] <= pos: lo=mid
        else: hi=mid
    return lo+1

def format_matches(text, matches, filename='(stdin)', include_line=True, all_lines=False, only=False):
    offs=line_offsets(text); lines=text.splitlines()
    byline={}
    for m in matches:
        sline=line_for_pos(offs,m.start); eline=line_for_pos(offs,max(m.end-1,m.start))
        for ln in range(sline, eline+1):
            ls=offs[ln-1]; le=offs[ln]-1 if ln < len(offs) else len(text)
            a=max(m.start,ls)-ls; b=min(m.end,le)-ls
            if b>a: byline.setdefault(ln,[]).append((a,b))
    output=[]
    total_lines=len(lines)
    line_iter=range(1,total_lines+1) if all_lines else sorted(byline)
    for ln in line_iter:
        ranges=byline.get(ln,[])
        if only and not ranges: continue
        ranges=merge_spans(ranges)
        rstr=';'.join(f"{a}-{b}" for a,b in ranges)
        content=lines[ln-1] if 1<=ln<=len(lines) else ''
        if include_line:
            output.append(f"{filename}:{ln}:{rstr}:{content}")
        else:
            output.append(f"{filename}:{rstr}:{content}")
    return '\n'.join(output) + ('\n' if output else '')

def process_text(text, o, filename='(stdin)'):
    spans=language_spans(text, o.lang_scopes, o.join_lang)
    matches=find_matches(text, spans, o.scope, o.literal)
    any_match=bool(matches)
    if o.fail_any and any_match: raise RuntimeSrgnError("Error applying: Some input was in scope")
    if o.fail_none and not any_match: raise RuntimeSrgnError("Error applying: No input was in scope")
    actions = o.delete or o.squeeze or has_composable(o)
    search_mode = bool(o.lang_scopes) and not actions
    if search_mode:
        if not any_match: raise RuntimeSrgnError("Error applying: No input was in scope")
        return format_matches(text,matches,filename,include_line=True,all_lines=False), False
    if actions:
        return apply_actions(text,matches,o), any_match
    # No actions, not language-search.
    sys.stderr.write("[2026-05-07T18:00:00.000000Z ERROR srgn] No actions specified, and not in search mode. Will return input unchanged, if any.\n")
    if o.only_matching or o.line_numbers:
        return format_matches(text,matches,filename,include_line=o.line_numbers,all_lines=o.line_numbers,only=o.only_matching), False
    return text, False

def discover_files(pattern, hidden=False):
    res=[]
    for root, dirs, files in os.walk('.'):
        if not hidden:
            dirs[:] = [d for d in dirs if not d.startswith('.')]
            files = [f for f in files if not f.startswith('.')]
        # skip .git unless explicitly hidden
        if not hidden and '.git' in dirs: dirs.remove('.git')
        for f in files:
            path=os.path.join(root,f)
            rel=path[2:] if path.startswith('./') else path
            if fnmatch.fnmatch(rel,pattern) or fnmatch.fnmatch(f,pattern):
                res.append(rel)
            elif pattern.startswith('**/') and fnmatch.fnmatch(rel, pattern[3:]):
                res.append(rel)
    # stable unique
    seen=[]
    for p in res:
        if p not in seen: seen.append(p)
    return seen

def dry_run_output(old,new,filename,o):
    if old==new: return ''
    out=[]
    old_lines=old.splitlines(); new_lines=new.splitlines(); maxn=max(len(old_lines),len(new_lines))
    for i in range(maxn):
        ol=old_lines[i] if i<len(old_lines) else ''
        nl=new_lines[i] if i<len(new_lines) else ''
        if ol!=nl:
            # Match ranges from original scope on the old line if possible.
            lm=find_matches(ol, [(0,len(ol))], o.scope, o.literal) if ol else []
            rng=';'.join(f"{m.start}-{m.end}" for m in lm) if lm else ''
            out.append(f"{filename}:{i+1}:{rng}:{ol}")
            out.append(f"{filename}:{i+1}:{rng}:{nl}")
    return '\n'.join(out)+('\n' if out else '')

def main(argv):
    try:
        o=parse(argv)
        if o.glob:
            files=discover_files(o.glob,o.hidden)
            if o.sorted: files=sorted(files)
            if not files and o.fail_no_files:
                # match original: may still log no-action before the error
                if not (o.delete or o.squeeze or has_composable(o) or o.lang_scopes):
                    sys.stderr.write("[2026-05-07T18:00:00.000000Z ERROR srgn] No actions specified, and not in search mode. Will return input unchanged, if any.\n")
                raise RuntimeSrgnError("No files found")
            allout=[]
            for p in files:
                try:
                    data=open(p,'r',encoding='utf-8').read()
                except Exception:
                    continue
                out,changed=process_text(data,o,p)
                actions=o.delete or o.squeeze or has_composable(o)
                if o.dry_run and actions:
                    new=out; diff=dry_run_output(data,new,p,o)
                    if diff: allout.append(diff)
                elif actions:
                    if out != data:
                        open(p,'w',encoding='utf-8').write(out)
                    allout.append(p+'\n')
                else:
                    if out: allout.append(out)
            sys.stdout.write(''.join(allout))
            return 0
        data=sys.stdin.read()
        out,_=process_text(data,o,'(stdin)')
        sys.stdout.write(out)
        return 0
    except CliError as ex:
        eprint(str(ex)); return 2
    except RuntimeSrgnError as ex:
        eprint("Error: "+str(ex)); return 1
    except BrokenPipeError:
        return 0

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
