@dataclass
class Opts:
    upper: bool=False; lower: bool=False; titlecase: bool=False; normalize: bool=False
    german: bool=False; symbols: bool=False; delete: bool=False; squeeze: bool=False
    invert: bool=False; literal: bool=False; dry_run: bool=False; fail_no_files: bool=False
    fail_any: bool=False; fail_none: bool=False; join_lang: bool=False; hidden: bool=False
    gitignored: bool=False; sorted: bool=False; only_matching: bool=False; line_numbers: bool=False
    german_prefer_original: bool=False; german_naive: bool=False
    glob: str|None=None; scope: str|None=None; replacement: str|None=None
    lang_scopes: list=field(default_factory=list)
