def parse(argv):
    o=Opts()
    envmap=[('UPPER','upper'),('LOWER','lower'),('TITLECASE','titlecase'),('NORMALIZE','normalize'),('INVERT','invert'),('LITERAL_STRING','literal'),('SQUEEZE','squeeze'),('GERMAN_PREFER_ORIGINAL','german_prefer_original'),('GERMAN_NAIVE','german_naive')]
