    if 'RUST' in os.environ: o.lang_scopes.append(('rust',os.environ['RUST']))
    if 'GO' in os.environ: o.lang_scopes.append(('go',os.environ['GO']))
    if 'C' in os.environ: o.lang_scopes.append(('c',os.environ['C']))
    if 'CSHARP' in os.environ: o.lang_scopes.append(('csharp',os.environ['CSHARP']))
    if 'TYPESCRIPT' in os.environ: o.lang_scopes.append(('typescript',os.environ['TYPESCRIPT']))
    if 'HCL' in os.environ: o.lang_scopes.append(('hcl',os.environ['HCL']))
    pos=[]; i=0
    while i < len(argv):
        a=argv[i]
        if a == '--':
            if i+1 < len(argv): o.replacement=argv[i+1]
            if i+2 < len(argv):
                # clap would reject, but keeping first replacement is ergonomic
                pass
            break
        if a in ('-h','--help'):
            print(SHORT_HELP, end=''); sys.exit(0)
        if a in ('-V','--version'):
            print(VERSION); sys.exit(0)
        if a == '--completions':
            # Consume shell and print a small but valid-ish completion script.
            if i+1 >= len(argv): raise CliError("error: a value is required for '--completions <SHELL>' but none was supplied\n\nFor more information, try '--help'.")
            shell=argv[i+1]; i+=2
            print(f"# completion script for executable ({shell})")
            sys.exit(0)
        if a.startswith('--completions='):
            shell=a.split('=',1)[1]; print(f"# completion script for executable ({shell})"); sys.exit(0)
        if a in LANG_OPTS or a in QUERY_OPTS:
            if i+1 >= len(argv): raise CliError(f"error: a value is required for '{a}' but none was supplied\n\nFor more information, try '--help'.")
            lang = LANG_OPTS.get(a) or QUERY_OPTS.get(a)
            val = argv[i+1]
            if a in QUERY_OPTS and a.endswith('-file'):
