                o.lang_scopes.append(((LANG_OPTS.get(key) or QUERY_OPTS.get(key)), '__query__' if key in QUERY_OPTS else val)); i+=1; continue
            a=key; argv=argv[:i]+[a,val]+argv[i+1:]
        if a in ('--upper',): o.upper=True; i+=1; continue
        if a in ('--lower',): o.lower=True; i+=1; continue
        if a in ('--titlecase',): o.titlecase=True; i+=1; continue
        if a in ('--normalize',): o.normalize=True; i+=1; continue
        if a in ('--german',): o.german=True; i+=1; continue
        if a in ('--symbols',): o.symbols=True; i+=1; continue
        if a in ('--delete',): o.delete=True; i+=1; continue
        if a in ('--squeeze','--squeeze-repeats'): o.squeeze=True; i+=1; continue
        if a in ('--invert',): o.invert=True; i+=1; continue
        if a in ('--literal-string',): o.literal=True; i+=1; continue
        if a in ('--dry-run',): o.dry_run=True; i+=1; continue
        if a in ('--fail-no-files',): o.fail_no_files=True; i+=1; continue
        if a in ('--fail-any',): o.fail_any=True; i+=1; continue
        if a in ('--fail-none',): o.fail_none=True; i+=1; continue
        if a in ('--join-language-scopes',): o.join_lang=True; i+=1; continue
        if a in ('--hidden',): o.hidden=True; i+=1; continue
        if a in ('--gitignored',): o.gitignored=True; i+=1; continue
        if a in ('--sorted',): o.sorted=True; i+=1; continue
        if a in ('--german-prefer-original',): o.german_prefer_original=True; i+=1; continue
        if a in ('--german-naive',): o.german_naive=True; i+=1; continue
        if a in ('--only-matching','--only-match'): o.only_matching=True; i+=1; continue
        if a in ('--line-numbers','--line-number'): o.line_numbers=True; i+=1; continue
        if a in ('--glob','--files'):
            if i+1 >= len(argv): raise CliError("error: a value is required for '--glob <GLOB>' but none was supplied\n\nFor more information, try '--help'.")
            o.glob=argv[i+1]; i+=2; continue
        if a in ('--stdin-detection','--stdout-detection','--threads'):
            if i+1 >= len(argv): raise CliError(f"error: a value is required for '{a}' but none was supplied\n\nFor more information, try '--help'.")
            i+=2; continue
        if a.startswith('--'):
            raise CliError(f"error: unexpected argument '{a}' found\n\nUsage: executable [OPTIONS] [SCOPE] [-- <REPLACEMENT>]\n\nFor more information, try '--help'.")
        if a.startswith('-') and a != '-':
            # short clusters
            j=1
            while j < len(a):
                c=a[j]
                if c=='u': o.upper=True
                elif c=='l': o.lower=True
                elif c=='t': o.titlecase=True
                elif c=='n': o.normalize=True
                elif c=='g': o.german=True
                elif c=='S': o.symbols=True
                elif c=='d': o.delete=True
                elif c=='s': o.squeeze=True
                elif c=='i': o.invert=True
                elif c=='L': o.literal=True
                elif c=='j': o.join_lang=True
                elif c=='H': o.hidden=True
